"""Bounded delivery of semantics; no new scientific eligibility is inferred."""
import copy
import json
from pathlib import Path
import sys
import tempfile
import unittest

import numpy as np
import tifffile

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from tools import image_evidence as evidence
from tools import image_workspace as worker


def semantics():
    # Independent contract fixture, not generated by the production adapter.
    def row(aspect, status):
        return {"aspect": aspect, "scope": "the saved image-frequency candidates", "status": status,
                "basis": "Only the named calculation was checked", "source_fields": ["peak_table"]}
    return {"version": 1, "scope": "candidate_measurement_and_assisted_interpretation",
            "numerical": {"execution": "completed", "scope": "candidate calculation", "checks": [row("geometry", "satisfied")]},
            "measurement_reliability": {"scope": "candidate measurement", "assessments": [row("noise_significance", "not_assessed")]},
            "interpretation": {"scope": "finite material interpretation", "assessments": [row("physical_identity", "insufficient_evidence")]}}


def project(value):
    return evidence._semantics_projection({"result_semantics": value})


class ProjectionContract(unittest.TestCase):
    def test_known_scopes_are_exact_copies_without_promoting_valid(self):
        value = semantics()
        result = evidence._semantics_projection({"status": "valid", "result_semantics": value})
        self.assertEqual(result, {"result_semantics": value})
        self.assertEqual(result["result_semantics"]["measurement_reliability"]["assessments"][0]["status"], "not_assessed")
        self.assertEqual(result["result_semantics"]["interpretation"]["assessments"][0]["status"], "insufficient_evidence")
        result["result_semantics"]["numerical"]["scope"] = "local edit"
        self.assertEqual(value["numerical"]["scope"], "candidate calculation")

    def test_absent_is_not_backfilled_and_unknown_bounded_raw_is_preserved(self):
        self.assertEqual(evidence._semantics_projection({"status": "valid"}), {})
        value = {"version": 99, "future": {"qualification": "unknown", "values": [None, True, 2, 0.25]}}
        result = project(value)
        self.assertEqual(result["result_semantics"], value)
        self.assertEqual(result["result_semantics_projection"]["status"], "unavailable")
        # A bounded extension is preserved as raw data, never converted to a known check.
        value = semantics()
        value["future_note"] = {"text": "not interpreted by this version"}
        self.assertEqual(project(value)["result_semantics"], value)

    def test_incomplete_v1_and_boolean_version_are_unavailable(self):
        cases = [{"version": 1}, {"version": True}, None, [], "future"]
        for change in ({"version": True}, {"scope": "another_scope"}, {"numerical": {}},
                       {"measurement_reliability": {"scope": "unknown", "assessments": None}}):
            cases.append({**semantics(), **change})
        for value in cases:
            with self.subTest(value=value):
                result = project(value)
                self.assertEqual(result.get("result_semantics_projection", {}).get("status"), "unavailable")
                self.assertEqual(result["result_semantics"], value)

    def test_assessment_status_shape_and_counts_are_checked_without_coercion(self):
        cases = []
        for status in (["satisfied"], "valid", True):
            value = semantics()
            value["numerical"]["checks"][0]["status"] = status
            cases.append(value)
        for field, bad in (("aspect", ""), ("scope", None), ("basis", 42),
                           ("source_fields", ["x"] * 9), ("source_fields", [""])):
            value = semantics()
            value["numerical"]["checks"][0][field] = bad
            cases.append(value)
        value = semantics()
        value["numerical"]["checks"] *= 13
        cases.append(value)
        for value in cases:
            with self.subTest(value=value):
                result = project(value)
                self.assertEqual(result.get("result_semantics_projection", {}).get("status"), "unavailable")
                self.assertEqual(result["result_semantics"], value)

    def test_24kib_boundary_is_exact_and_never_truncated(self):
        value = semantics()
        value["padding"] = ["x" * 1000 for _ in range(23)] + [""]
        encoded = lambda v: json.dumps(v, ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode()
        missing = 24 * 1024 - len(encoded(value))
        self.assertGreaterEqual(missing, 0)
        self.assertLessEqual(missing, 1024)
        value["padding"][-1] = "x" * missing
        self.assertEqual(len(encoded(value)), 24 * 1024)
        self.assertEqual(project(value), {"result_semantics": value})
        value["padding"][-1] += "x"
        result = project(value)
        self.assertNotIn("result_semantics", result)
        self.assertEqual(result["result_semantics_projection"]["reason"], "invalid_or_over_budget")
        self.assertEqual(len(encoded(value)), 24 * 1024 + 1)

    def test_unicode_string_budget_matches_browser_utf16_units(self):
        value = {"version": 99, "future": "😀" * 512}
        self.assertEqual(project(value)["result_semantics"], value)
        value["future"] += "😀"
        self.assertNotIn("result_semantics", project(value))

    def test_non_json_nonfinite_and_recursive_input_is_unavailable(self):
        cyclic = {}; cyclic["self"] = cyclic
        for value in ({"number": float("nan")}, {"number": float("inf")}, {"not_json": (1, 2)},
                      {"text": "x" * 1025}, {"list": [0] * 33}, cyclic):
            with self.subTest(kind=type(value).__name__):
                result = project(value)
                self.assertNotIn("result_semantics", result)
                self.assertEqual(result["result_semantics_projection"]["status"], "unavailable")


class SavedProjectionChain(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory(prefix="semantics-projection-")
        cls.root = Path(cls.temp.name).resolve()
        cls.workspace = cls.root / "workspace"
        source = cls.root / "public-periodic.tiff"
        y, x = np.indices((64, 64))
        tifffile.imwrite(source, (np.cos(2*np.pi*x/8) + np.cos(2*np.pi*y/16)).astype(np.float32))
        opened = cls.call("open", request_id="open", source_path=str(source))
        frame = cls.call("frame", request_id="frame", object_id=opened["object_id"], frame_index=0)
        cls.field = cls.call("spatial_field", request_id="field", object_id=frame["object_id"], window_sizes=[32],
                             stride_xy=[32, 32], max_windows=4, coordinate_domain="pixel", max_size=256,
                             max_peaks=4, window="none", subtract_mean=True,
                             peak_options={"threshold_rel": .18, "refinement": "quadratic"})
        cls.protected = {p: p.read_bytes() for p in cls.root.rglob("*") if p.is_file()}

    @classmethod
    def tearDownClass(cls):
        try:
            for path, value in cls.protected.items():
                assert path.read_bytes() == value, path
        finally:
            cls.temp.cleanup()

    @classmethod
    def call(cls, action, **arguments):
        response = worker.execute(dict(action=action, workspace=str(cls.workspace), **arguments))
        if not response.get("ok"):
            raise AssertionError(response)
        return response["result"]

    def test_saved_full_compact_page_and_recovery_preserve_same_semantics(self):
        full = self.field
        compact = self.call("get", object_id=full["object_id"], response_detail="compact")
        detail = self.call("evidence", object_id=full["object_id"], manifest_sha256=compact["manifest_sha256"],
                           section="samples", offset=0, limit=1)
        for record in (compact, detail, self.call("result", query_request_id="field", response_detail="compact")):
            self.assertEqual(record["result_semantics"], full["result_semantics"])
            self.assertNotIn("result_semantics_projection", record)
        self.assertEqual(detail["rows"], full["samples"][:1])
        for projected, original in zip(compact["samples"], full["samples"]):
            self.assertEqual(projected["status"], original["status"])
        self.assertEqual(self.call("result", query_request_id="field"), full)

    def test_measurement_compact_retains_unknown_reliability_and_original_bytes(self):
        ident = self.field["samples"][0]["measurement_object_ids"][0]
        full = self.call("get", object_id=ident)
        compact = self.call("get", object_id=ident, response_detail="compact")
        self.assertEqual(compact["result_semantics"], full["result_semantics"])
        noise = [a for a in full["result_semantics"]["measurement_reliability"]["assessments"] if a["aspect"] == "noise_significance"]
        self.assertEqual(noise[0]["status"], "not_assessed")


if __name__ == "__main__":
    unittest.main()
